"""Per-shot UI for the approved portrait and half-body plans."""
from pathlib import Path

import bpy
from bpy.props import IntProperty, EnumProperty

from . import animchar

_PREVIEWS = None

# Semantic instructions follow the approved photo designs. Joint rotations,
# finger angles and IK targets are generated by the installed AnimChar tool.
PORTRAIT_PROMPTS = {
    5: 'Standing anime portrait pose, one hand making a V sign beside the cheek, other arm relaxed down, shoulders relaxed, hold the pose still, do not cover the face.',
    6: 'Standing surprised anime portrait pose, both hands raised near the upper chest with softly curled fingers, relaxed wrists, face unobstructed, hold the pose still.',
    7: 'Standing naturally and elegantly for a sweet smiling portrait, arms relaxed at the sides, subtle relaxed head tilt, hold the pose still.',
    8: 'Standing shy anime portrait pose, hands softly gathered in front of the upper chest, fingers relaxed, slight head tilt, do not cover the face, hold the pose still.',
    9: 'Standing playful portrait pose, one index finger gently touches the cheek beside the mouth, other fingers curled naturally, other arm relaxed, hold the pose still.',
    10: 'Standing confident tsundere anime portrait pose, one hand resting naturally on the side of the waist, other arm relaxed down, subtle body weight shift, hold the pose still.',
    11: 'Standing cheerful anime portrait pose, both arms raised energetically with softly closed fists, elbows bent, face unobstructed, hold the pose still.',
    12: 'Standing gentle over shoulder portrait pose, torso turned slightly away and head looking back comfortably, hands relaxed behind the lower back, no extreme neck twist, hold the pose still.',
}


def selected(settings):
    from . import dataset_plan
    return next(s for s in dataset_plan(settings) if s['group'] == settings.preview_group and s['index'] == settings.plan_index)


def reference_path(settings, shot):
    if settings.animchar_reference:
        return Path(bpy.path.abspath(settings.animchar_reference))
    package = Path(__file__).parent
    path = package/shot.get('reference_image', '')
    return path if path.is_file() else package.parent/shot.get('reference_image', '')


def preview_icon(path):
    global _PREVIEWS
    if not path.is_file():
        return 0
    if _PREVIEWS is None:
        import bpy.utils.previews
        _PREVIEWS = bpy.utils.previews.new()
    key = str(path)
    if key not in _PREVIEWS:
        _PREVIEWS.load(key, key, 'IMAGE')
    return _PREVIEWS[key].icon_id


def clear_previews():
    global _PREVIEWS
    if _PREVIEWS is not None:
        import bpy.utils.previews
        bpy.utils.previews.remove(_PREVIEWS)
        _PREVIEWS = None


class ML_OT_select_shot(bpy.types.Operator):
    bl_idname = 'ml.select_shot'; bl_label = '选择编排镜头'
    index: IntProperty(min=1, max=12)

    def execute(self, context):
        context.scene.ml_settings.plan_index = self.index
        context.scene.ml_settings.animchar_reference = ''
        return {'FINISHED'}


class ML_OT_animchar(bpy.types.Operator):
    bl_idname = 'ml.animchar'; bl_label = 'AnimChar 动作工作流'; bl_options = {'REGISTER', 'UNDO'}
    action: EnumProperty(items=[(v, v, '') for v in ('RESTORE', 'CONFIGURE', 'CAPTURE', 'TEXT', 'BIND', 'REVIEW', 'NEEDS_FIX', 'EDIT', 'FINISH_EDIT', 'CANCEL_EDIT', 'REFERENCE')])

    @classmethod
    def poll(cls, context):
        return not context.scene.ml_settings.running and not animchar.busy()

    def execute(self, context):
        settings = context.scene.ml_settings
        try:
            shot = selected(settings)
            if animchar.editing() and self.action not in {'FINISH_EDIT', 'CANCEL_EDIT', 'REFERENCE'}:
                raise ValueError('请先完成或取消当前 AnimChar 编辑。')
            if self.action == 'RESTORE':
                result = animchar.restore_results(settings)
                settings.animchar_status = f'本地已保存 {result["total"]} 份动作，本次恢复 {result["restored"]} 份。'
            elif self.action == 'REFERENCE':
                bpy.ops.wm.url_open(url=f'https://github.com/haotemans/AniForge/pull/{shot.get("reference_pr", 1)}')
            elif self.action == 'CONFIGURE':
                values = animchar.configure(settings)
                settings.animchar_status = f'已向 AnimChar 配置 {len(values)} 个骨骼映射。'
            elif self.action == 'CAPTURE':
                animchar.start_capture(context, settings, shot, reference_path(settings, shot))
            elif self.action == 'TEXT':
                prompt = settings.animchar_prompt or PORTRAIT_PROMPTS.get(shot['index'], '')
                if not prompt.strip():
                    raise ValueError('请填写此镜头的动作描述。')
                animchar.start_capture(context, settings, shot, '', text_prompt=prompt)
            elif self.action == 'BIND':
                animchar.configure(settings)
                animchar.bind(settings, shot)
                settings.animchar_status = '已保存当前 AnimChar 结果，等待镜头验收。'
            elif self.action == 'REVIEW':
                animchar.mark_reviewed(settings, shot)
                settings.animchar_status = '此模型、此镜头已标记验收。'
            elif self.action == 'NEEDS_FIX':
                animchar.mark_needs_fix(settings, shot, settings.animchar_review_note)
                settings.animchar_status = '已标记待修；单张预览保留，完整批次等待修正。'
            elif self.action == 'EDIT':
                animchar.start_editor(context, settings, shot)
            elif self.action == 'FINISH_EDIT':
                animchar.finish_editor(context, settings)
            elif self.action == 'CANCEL_EDIT':
                animchar._close_editor(context, settings)
                settings.animchar_status = '已取消编辑，恢复原角色。'
            return {'FINISHED'}
        except Exception as exc:
            settings.animchar_status = str(exc)
            self.report({'ERROR'}, str(exc))
            return {'CANCELLED'}


def draw_shots(layout, settings):
    from . import dataset_plan
    shots = dataset_plan(settings)
    layout.prop(settings, 'preview_group', text='照片分组')
    layout.operator('ml.animchar', text='恢复本地已保存结果（不重新生成）').action = 'RESTORE'
    box = layout.box()
    box.label(text='肖像 12 · 半身 12 · 全身 9 · 衣服 9')
    for shot in (s for s in shots if s['group'] == settings.preview_group):
        status = shot.get('asset_status', '')
        icon = {'MISSING': 'RADIOBUT_OFF', 'CAPTURED': 'TIME', 'NEEDS_FIX': 'ERROR', 'REVIEWED': 'CHECKMARK', 'CUSTOM': 'USER'}.get(status, 'DOT')
        op = box.operator('ml.select_shot', text=f'{shot["index"]:02}  {shot["title"]}', icon=icon,
                          depress=shot['index'] == settings.plan_index)
        op.index = shot['index']
    shot = selected(settings)
    box = layout.box()
    box.label(text=f'{shot["index"]:02} · {shot["title"]}')
    angle = shot['azimuth']
    aspect = '1:1 方形' if shot['group'] == 'portrait' else '3:4 竖幅'
    box.label(text=f'{angle:g}° · {shot.get("camera", {}).get("camera_lens", settings.camera_lens):g} mm · {aspect} · 白底')
    if shot.get('pose_provider') == 'AnimCharTools':
        status = {'MISSING': '待制作 AnimChar 动作', 'CAPTURED': '已捕捉，待检查手型与构图', 'NEEDS_FIX': '此镜头待修，尚未验收', 'REVIEWED': '此模型已验收'}.get(shot.get('asset_status'), '未绑定')
        box.label(text=status, icon='INFO')
        if shot.get('review_note'):
            box.label(text=shot['review_note'])
        path = reference_path(settings, shot)
        icon = preview_icon(path)
        if icon:
            box.template_icon(icon_value=icon, scale=6)
        box.operator('ml.animchar', text='查看已确认的 PR 规范').action = 'REFERENCE'
        box.prop(settings, 'animchar_reference', text='替换参考图')
        if not animchar.available():
            box.label(text='先启用已安装的 AnimChar Tools', icon='ERROR')
        controls = box.column(); controls.enabled = animchar.available() and not animchar.busy()
        if animchar.available():
            controls.prop(bpy.context.scene.animchartools_props, 'use_general_model', text='AnimChar 通用识别模型')
            controls.prop(bpy.context.scene.animchartools_props, 'use_pose_optimization', text='AnimChar 姿势优化')
            controls.prop(settings, 'animchar_rebuild')
        controls.operator('ml.animchar', text='1 · 配置 AnimChar 骨骼映射').action = 'CONFIGURE'
        controls.operator('ml.animchar', text='2 · AnimChar 自然站姿适配' if shot.get('asset_slot') == 'neutral' and not path.is_file() else '2 · AnimChar 从参考图捕捉').action = 'CAPTURE'
        if shot['group'] == 'portrait' and shot['index'] > 4:
            controls.prop(settings, 'animchar_prompt', text='替换动作描述')
            controls.operator('ml.animchar', text='AnimChar 按肖像规范生成动作').action = 'TEXT'
        if not path.is_file() and shot.get('asset_slot') != 'neutral':
            controls.label(text='此镜头请指定参考图，或用 Pose Editor 制作')
        controls.operator('ml.animchar', text='用 AnimChar 标准角色编辑动作').action = 'EDIT'
        controls.operator('ml.animchar', text='完成编辑并保存此镜头').action = 'FINISH_EDIT'
        if animchar.editing():
            controls.operator('ml.animchar', text='取消编辑，恢复原角色').action = 'CANCEL_EDIT'
        controls.operator('ml.animchar', text='保存已应用的 AnimChar 结果').action = 'BIND'
        ready = box.column(); ready.enabled = shot.get('asset_status') in {'CAPTURED', 'NEEDS_FIX', 'REVIEWED'} and not animchar.busy() and not animchar.editing()
        ready.operator('ml.shot_plan', text='3 · 预览姿势 / 表情 / 镜头（不出图）')
        ready.operator('ml.animchar', text='4 · 标记此模型此镜头已验收').action = 'REVIEW'
        ready.prop(settings, 'animchar_review_note')
        ready.operator('ml.animchar', text='标记此镜头待修').action = 'NEEDS_FIX'
        ready.operator('ml.preview', text='渲染当前镜头 1 张').use_plan_shot = True
        if settings.developer_tools:
            op = ready.operator('ml.render_dataset', text='开发检查：此动作正 / 侧 / 背')
            op.test_only = True; op.use_plan_shot = True
    else:
        box.operator('ml.shot_plan', text='预览此镜头（不出图）')
        box.operator('ml.preview', text='渲染此镜头 1 张').use_plan_shot = True
    if settings.animchar_status:
        layout.label(text=settings.animchar_status)
    pending = sum(s.get('asset_status') == 'MISSING' for s in shots)
    reviewed = sum(s.get('asset_status') == 'REVIEWED' for s in shots)
    failed = sum(s.get('asset_status') == 'NEEDS_FIX' for s in shots)
    layout.label(text=f'AnimChar：待绑定 {pending} · 已验收 {reviewed} · 待修 {failed}')
    layout.prop(settings, 'developer_tools')


CLASSES = (ML_OT_select_shot, ML_OT_animchar)
